import json, sys
from openpyxl import load_workbook
from openpyxl.styles import Font

path = "sales_data.xlsx"
wb = load_workbook(path)
ws = wb.active

header_row = 1
headers = {}
for cell in ws[header_row]:
    if cell.value is not None:
        headers[cell.column] = str(cell.value).strip().lower()

def pick(cands):
    for cand in cands:
        for col, name in headers.items():
            if name == cand:
                return col
    for cand in cands:
        for col, name in headers.items():
            if cand in name:
                return col
    return None

profit_col = pick(["profit"])
revenue_col = pick(["revenue", "total revenue", "net revenue", "gross revenue", "sales", "total sales", "net sales", "gross sales"])

print(json.dumps({"sheets": wb.sheetnames, "headers": headers, "profit_col": profit_col, "revenue_col": revenue_col, "max_row": ws.max_row, "max_col": ws.max_column}))

if profit_col is None or revenue_col is None:
    sys.exit(2)

new_col = ws.max_column + 1
hcell = ws.cell(row=header_row, column=new_col, value="Profit Margin %")
hcell.font = Font(bold=True)

for row in range(header_row + 1, ws.max_row + 1):
    if all(ws.cell(row=row, column=c).value is None for c in headers):
        continue
    p = ws.cell(row=row, column=profit_col).coordinate
    r = ws.cell(row=row, column=revenue_col).coordinate
    cell = ws.cell(row=row, column=new_col, value=f"=IFERROR({p}/{r},0)")
    cell.number_format = "0.0%"

wb.save(path)
print("saved")

import importlib, sys
for m in ["openpyxl", "pandas", "lxml"]:
    try:
        importlib.import_module(m)
        print(m, "OK")
    except Exception as e:
        print(m, "MISSING", type(e).__name__)
print("python:", sys.executable)

